// B2 course (B1 → B2 roadmap), module 3 „Minevik ja kogemused” (b1b2-011…015), stage B1+.
// Methodology v5 „lesson budget” (docs/METHODOLOGY_B1_B2_V5.md, strictModulesV5.json) on the v3 station engine with the
// v4 task formats (docs/COURSE_DESIGN_STATIONS.md §7), built like modules 1 and 2 (b2/module01.js, b2/module02.js): one
// real communicative outcome a lesson, ONE input, ≤ 4 / 4 / 5 blocks a sheet and ≤ 14 a lesson, a 75-min core in 4 stations.
//   Avasta  (4): station 1 one statement to answer at once (011: the module's cold task, a 5-minute WRITING without help —
//                module 2 measured speaking, module 3 measures writing), station 2 the lesson's words, one explanatory
//                scheme and the ONE input — reading 450–520 words with ≥ 3 inference questions (011, 013) or listening
//                ~3.5 min with 2 voices and 10 items (012, 014).
//   Harjuta (4): station 3 the rule (the A2/B1 form as a one-line review, then the B2 step), two form tasks of 8–10 items
//                without a word bank (one of them in a coherent text) and one register task (spoken → written).
//   Kasuta  (5): station 4 the plan, the product (a radio interview with hidden information, a call to the hike leader with
//                hidden information, explaining 1991 to a child with hidden information, a debate with keyword cards), the
//                home writing of ~140 or ~180 words with the 1-min voice message, the analytic Harno B2 rubric (a borderline
//                sample in the teacher's note) and the exit „Ma oskan …” with three success criteria.
//   011 project „Mis oli sinu lapsepõlve pühadelaual?”   family   reading „Peolaud räägib, kes me oleme”   impersonal past (söödi, tehti)
//   012 infogap „Kas sa oled kunagi rabas käinud?”       nature   radio talk with a hike guide, 2 voices   experience as an argument
//   013 case    „Teletorn, 21. august 1991 …”            culture  reading „Neli päeva, mis muutsid kõike”  order of events (selleks ajaks …)
//   014 debate  „Viga, millest ma õppisin”               money    radio talk on a phone scam, 2 voices     past conditional (oleksin pidanud)
//   015 exam    Kontroll 3: one sheet, 45 min, reading + writing (module 2: listening + speaking), raw points, thresholds.
// The A2–B1 grammar of the v4 lessons (lihtminevik as a whole lesson in 011, olen käinud / käisin in 012) is now the
// one-line review of each rule; every lesson lifts it to B2 use (audit 2026-11-25, docs/review/B1-B2-plaan-2026-11-25.md).
// Module requirements (v5 §2): cold task 011_d_cold (5-min opinion in writing, no phrases, no opening) ↔ parallel new task
// 015_t_cold (same conditions, new statement); a speech without phrases in every station 1 (012–014); hidden-information
// cards 011_t_talk, 012_t_talk, 013_t_child („Varjatud info:”); link tasks 012_t_reply (a real trail on loodusegakoos.ee)
// and 013_t_explain (a real source: teletorn.ee, ERR archive); one scheme a teaching lesson (011 compare, 012 formula,
// 013 timeline, 014 flow); the pictures (art/visuals/b2-module-03.js) stand before the input and ask what the input needs;
// texts are adapted learning texts without exact statistics („KeeleSepp õppetekst”, owner 2026-11-25); no story cast, no
// dictation, no „Kas teadsid?”.
// Removed blocks stay in the file as hide(block, why) (blocks.js): off every sheet, ids and learners' answers kept; their
// closed drills still feed the Harjuta practice engine (practice/engine/extract.js), with their old explanations.
// The v4 file of 2026-11-17 is in git history (before this commit).
import { B, hide, tag, teach, why, withShapes } from '../blocks.js';
import { exitCheck, extension, homeTask, purpose, station } from '../stationBlocks.js';

// a talk with the teacher as the partner, done in the lesson (engine/inLesson.js), not a home recording
const inLesson = (block) => ({ ...block, inLesson: true });
// the lesson's grammar as the small subtitle under the title on every sheet
const grammar = (text) => ({
  discover: { label: '1 Avasta', slot: 1, subtitle: text },
  practice: { label: '2 Harjuta', slot: 2, subtitle: text },
  transfer: { label: '3 Kasuta', slot: 3, subtitle: text },
});
// the home task card at the end of every lesson (v4; hidden in v5: the home task is the writing on the sheet)
const homework = (id, items) => B.phrasebank(id, [['Kodutöö', items]]);
const WORDS_HOME = 'Tunni sõnad: Sõnavara → Teemad → Moodul 3. Kui teema on läbitud, kordad sõnu „Harjuta” all.';
// a learner who cannot record (no quiet room, no smartphone) says the talk at the start of the next lesson
const NO_RECORDING = 'Kui salvestada ei saa, räägi see järgmise tunni alguses õpetajale.';
// the home voice message of v5 (§3): one line at the end of the home writing (a learner who cannot record says it in class)
const VOICE_HOME = 'Salvesta ka 1-minutiline häälsõnum samal teemal.';

// why a block left the sheet (v5 §4)
const CUT_INPUT = 'second input of the lesson (v5: one input per lesson)';
const CUT_DRILL = 'closed drill / exit gaps → Harjuta (v5 §4: drills off the lesson sheet)';
const CUT_EXTRA = 'extra task (v5: one product task in Kasuta; „Kui aega jääb” is in the teacher plan)';
const CUT_HOME = 'home card / voice task: the home task is the writing on the sheet with its 1-min voice message (v5 §3)';
const CUT_HOOK = 'v5: station 1 is one statement the learner answers at once (5 min); the hook text and the talk merged';
const CUT_A2 = 'A2–B1 grammar drill or sound game: below B2 (audit 2026-11-25), review line in the rule instead';
const CUT_STATS = 'exact statistics (owner 2026-11-25: adapted texts, no exact numbers) and a second input';
const CUT_TIP = '„Kas teadsid?” (v5 §4: cut unless the task uses it)';
const CUT_CONTROL = 'control is one sheet ≤ 10 blocks, reading + writing (v5 §5)';

// the analytic Harno B2 writing rubric (v5 G10): four criteria, 0–3 points each, with level descriptors; the teacher's
// note holds a borderline sample with its scoring (the same rubric as modules 1, 2, 17 and 18)
const B2_WRITING = [
  ['Ülesande täitmine ja register', '3 — kõik sisupunktid on täidetud, adressaat ja toon sobivad, pikkus on ülesande piires; 2 — üks punkt on nõrk või toon kõigub; 1 — kaks punkti on puudu või toon ei sobi adressaadile; 0 — tekst ei vasta ülesandele'],
  ['Ülesehitus ja sidusus', '3 — lõigud, teemalaused ja mitmekesised sidendid, mõte liigub loogiliselt; 2 — lõigud on olemas, kuid sidendid korduvad; 1 — mõtete loetelu ilma lõikudeta; 0 — järjekorrast ei saa aru'],
  ['Sõnavara', '3 — täpne ja mitmekesine, kordusi väldib; 2 — piisav, mõni kordus või ebatäpne sõna; 1 — piiratud, sõnad korduvad, tähendus on kohati segane; 0 — sõnavara ei kanna sisu'],
  ['Grammatika ja õigekiri', '3 — liitlaused ja vormid (käänded, mineviku ajad, tingiv kõneviis, sõnajärg) on enamasti õiged; 2 — vigu on, kuid need ei takista mõistmist; 1 — vead takistavad kohati mõistmist; 0 — vead takistavad mõistmist pidevalt'],
];
// short: the one-line descriptors (the same four criteria), where the full ones would leave the self-check alone on a page
const B2_WRITING_SHORT = ['3 kõik punktid, sobiv toon · 2 üks nõrk koht · 1 kaks puudu · 0 ei vasta', '3 lõigud ja mitmekesised sidendid · 2 sidendid korduvad · 1 loetelu · 0 segane', '3 täpne ja mitmekesine · 2 mõni kordus · 1 piiratud · 0 ei kanna sisu', '3 vead ei sega · 2 vead ei takista · 1 takistavad kohati · 0 takistavad pidevalt'];
const writingRubric = (id, title, sample, short = false) => {
  const b = B.rubricW2(id, title);
  return teach(purpose({ ...b, goal: 'g_use', data: { ...b.data, instruction: 'Analüütiline hindamisjuhend (Harno B2): neli kriteeriumi, igaüks 0–3 punkti, kokku 12. Sama juhendiga kontrollid oma teksti enne saatmist.', criteria: B2_WRITING.map(([name, hint], i) => ({ name, max: 3, hint: short ? B2_WRITING_SHORT[i] : hint })) } }, 'Enne saatmist näed, mille eest hindaja punkte annab.'), sample);
};
// a home text is written at home: fewer lines on the sheet, so the sheet ends on a full page
const homeLines = (b, lines) => ({ ...b, data: { ...b.data, lines } });
// an exam part header of the control
const PART = (id, skill, o) => ({ ...B.examPart(id, skill, o), goal: ['R', 'L'].includes(skill) ? 'g_read' : 'g_use' });

export const MODULE = { id: 'b1b2-module-03', course: 'b2', title: 'Minevik ja kogemused', level: 'B1+', design: 'v3-stations', template: 'v4' };

